def parser(log: str) -> dict[str, str]:
    import re
    import xml.etree.ElementTree as ET

    results: dict[str, str] = {}

    def add_result(name: str, status: str) -> None:
        if not name:
            return
        priority = {"pass": 0, "skip": 1, "fail": 2}
        current = results.get(name)
        if current is None or priority[status] > priority[current]:
            results[name] = status

    def local_tag(tag: str) -> str:
        return tag.split("}", 1)[1] if "}" in tag else tag

    def parse_testcase_elem(tc: ET.Element, suite_name: str | None = None) -> None:
        classname = tc.get("classname") or tc.get("class") or tc.get("classname")
        name = tc.get("name") or tc.get("testcase") or tc.get("method")
        if not classname and suite_name:
            classname = suite_name
        if classname and name:
            key = f"{classname}::{name}"
        else:
            key = classname or name or ""
        status = "pass"
        # Attributes sometimes carry status
        for attr in ("status", "result", "outcome"):
            val = tc.get(attr)
            if val:
                val_lower = val.lower()
                if "skip" in val_lower or "ignored" in val_lower:
                    status = "skip"
                elif "fail" in val_lower or "error" in val_lower:
                    status = "fail"
                elif "pass" in val_lower or "success" in val_lower:
                    status = "pass"
        # Child elements determine status
        for child in tc:
            tag = local_tag(child.tag).lower()
            if tag in ("failure", "error"):
                status = "fail"
                break
            if tag in ("skipped", "skip"):
                status = "skip"
        add_result(key, status)

    def process_suite(suite: ET.Element, parent_name: str | None = None) -> None:
        suite_name = suite.get("name") or suite.get("classname") or parent_name
        # Direct testcases
        for tc in suite.findall("./*"):
            if local_tag(tc.tag).lower() == "testcase":
                parse_testcase_elem(tc, suite_name)
        # Recurse into nested suites
        for child in suite:
            if local_tag(child.tag).lower() == "testsuite":
                process_suite(child, suite_name)

    def parse_xml(xml_text: str) -> None:
        try:
            root = ET.fromstring(xml_text)
        except ET.ParseError:
            return
        root_tag = local_tag(root.tag).lower()
        if root_tag == "testsuite":
            process_suite(root, None)
        elif root_tag == "testsuites":
            for suite in root:
                if local_tag(suite.tag).lower() == "testsuite":
                    process_suite(suite, None)
        else:
            # Fallback: find any testcase elements
            for tc in root.iter():
                if local_tag(tc.tag).lower() == "testcase":
                    parse_testcase_elem(tc, None)

    # Extract XML fragments (testsuite/testsuites)
    xml_patterns = [
        r"(<testsuites[\s\S]*?</testsuites>)",
        r"(<testsuite[\s\S]*?</testsuite>)",
    ]
    for pattern in xml_patterns:
        for match in re.findall(pattern, log):
            parse_xml(match)

    # Regex fallback for testcases if XML parsing failed or is partial
    # Handle <testcase .../> and <testcase ...>...</testcase>
    testcase_patterns = [
        r"<testcase\b([^>]*)/>",
        r"<testcase\b([^>]*)>([\s\S]*?)</testcase>",
    ]
    for pattern in testcase_patterns:
        for m in re.finditer(pattern, log):
            attrs = m.group(1) or ""
            body = m.group(2) if m.lastindex and m.lastindex >= 2 else ""
            attr_pairs = dict(re.findall(r'(\w+)=["\'](.*?)["\']', attrs))
            classname = attr_pairs.get("classname") or attr_pairs.get("class")
            name = attr_pairs.get("name")
            key = f"{classname}::{name}" if classname and name else classname or name or ""
            status = "pass"
            if re.search(r"<(failure|error)\b", body):
                status = "fail"
            elif re.search(r"<skipped\b", body):
                status = "skip"
            if attr_pairs.get("status"):
                val = attr_pairs["status"].lower()
                if "skip" in val:
                    status = "skip"
                elif "fail" in val or "error" in val:
                    status = "fail"
            add_result(key, status)

    # Parse common plain-text outputs
    for line in log.splitlines():
        line = line.strip()
        # pytest format
        m = re.match(r"^(.*?)::([^\s]+)\s+(PASSED|FAILED|SKIPPED|ERROR)\b", line)
        if m:
            test_name = f"{m.group(1)}::{m.group(2)}"
            status = m.group(3).lower()
            status = "fail" if status in ("failed", "error") else ("skip" if status == "skipped" else "pass")
            add_result(test_name, status)
            continue
        # unittest format
        m = re.match(r"^([\w\.]+)\s+\(.*\)\s+\.\.\.\s+(ok|FAIL|ERROR|SKIP|SKIPPED)\b", line)
        if m:
            test_name = m.group(1)
            outcome = m.group(2).lower()
            if outcome in ("fail", "error"):
                status = "fail"
            elif outcome.startswith("skip"):
                status = "skip"
            else:
                status = "pass"
            add_result(test_name, status)
            continue
        # Go test format
        m = re.match(r"^---\s+(PASS|FAIL|SKIP):\s+(\S+)", line)
        if m:
            outcome = m.group(1).lower()
            test_name = m.group(2)
            status = "fail" if outcome == "fail" else ("skip" if outcome == "skip" else "pass")
            add_result(test_name, status)
            continue
        # Jest symbols
        m = re.match(r"^(✓|✕|○)\s+(.*)", line)
        if m:
            symbol = m.group(1)
            test_name = m.group(2).strip()
            status = "pass" if symbol == "✓" else ("fail" if symbol == "✕" else "skip")
            add_result(test_name, status)
            continue
        # Jest keywords
        m = re.match(r"^(PASS|FAIL)\s+(.+)", line)
        if m:
            outcome = m.group(1).lower()
            test_name = m.group(2).strip()
            status = "pass" if outcome == "pass" else "fail"
            add_result(test_name, status)
            continue

    return results
